import React, { useState, useEffect } from 'react';

const AnimatedHelloWorld = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [message, setMessage] = useState('Hello World!');

  const handleShow = () => {
    setIsVisible(true);
  };

  // Simple animation effect using state change
  useEffect(() => {
    if (isVisible) {
      const timer = setTimeout(() => {
        // Simulate a brief animation/display time
        setMessage('✨ Animated Hello World! ✨');
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [isVisible]);

  return (
    <div>
      {/* CRITICAL UNBREAKABLE CODE RULE 1: Must render a launcher button if visibility is toggled/managed */}
      {!isVisible && (
        <button onClick={handleShow} style={{ padding: '10px 20px', fontSize: '16px', cursor: 'pointer' }}>
          🚀 Launch Animated Greeting
        </button>
      )}

      {/* Display the animated content when visible */}
      {isVisible && (
        <div 
          style={{
            padding: '20px',
            border: '2px solid #4CAF50',
            borderRadius: '8px',
            backgroundColor: '#e8f5e9',
            textAlign: 'center',
            transition: 'all 0.5s ease-in-out',
            opacity: 1,
            transform: 'scale(1)'
          }}
        >
          <h1 style={{ color: '#2e7d32' }}>{message}</h1>
          <p style={{ marginTop: '10px', color: '#388e3c' }}>This message appears after the button is pressed!</p>
          <button 
            onClick={() => setIsVisible(false)} 
            style={{ marginTop: '15px', padding: '8px 15px', cursor: 'pointer' }}
          > 
            Close
          </button>
        </div>
      )}
    </div>
  );
};

export default AnimatedHelloWorld;
